window.DOTA_QUOTES=[{"hero": 1, "text": "В храбром сердце нет места страху.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/0/0c/Anti_respawn_06_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Anti-Mage.json"}, {"hero": 1, "text": "Мою расправу они не скоро забудут.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/0/04/Anti_respawn_09_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Anti-Mage.json"}, {"hero": 2, "text": "A cut above the rest.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/2/23/Vo_axe_axe_spawn_04.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Axe.json"}, {"hero": 2, "text": "I said good day sir.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/8/8e/Vo_axe_axe_deny_16.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Axe.json"}, {"hero": 3, "text": "I come with evil dreams.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/0/06/Vo_bane_bane_spawn_07.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Bane.json"}, {"hero": 3, "text": "I wake from dark dreaming.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/9/93/Vo_bane_bane_respawn_07.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Bane.json"}, {"hero": 4, "text": "Река моей жизни полна крови.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/7/75/Blod_rare_04_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Bloodseeker.json"}, {"hero": 4, "text": "Меня сразили но я встаю вновь.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/6/63/Blod_respawn_06_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Bloodseeker.json"}, {"hero": 5, "text": "Никто бы не угадал чьи стихи я люблю.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/b/b9/Cm_rare_02_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Crystal%20Maiden.json"}, {"hero": 5, "text": "Душа моя не растает даже если тело сжечь.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/9/91/Cm_rare_04_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Crystal%20Maiden.json"}, {"hero": 6, "text": "That was just a warm up.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/8/8b/Vo_drowranger_dro_respawn_07.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Drow%20Ranger.json"}, {"hero": 6, "text": "Beware the bite of frost.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/3/3a/Vo_drowranger_dro_spawn_06.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Drow%20Ranger.json"}, {"hero": 7, "text": "Трясётся ли земля под тобой.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/7/7e/Erth_rare_01_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Earthshaker.json"}, {"hero": 7, "text": "От меня так просто не избавишься.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/a/ad/Erth_respawn_04_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Earthshaker.json"}, {"hero": 8, "text": "Я потерял лицо но не потерял дух.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/d/d9/Jug_respawn_05_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Juggernaut.json"}, {"hero": 8, "text": "Враги падут от взмаха моего меча.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/c/c1/Jug_rare_03_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Juggernaut.json"}, {"hero": 9, "text": "Этой ночью нас ждёт бой.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/a/a0/Mir_spawn_10_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Mirana.json"}, {"hero": 9, "text": "Смотри как добыча нас боится.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/d/d9/Mir_battlebegins_01_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Mirana.json"}, {"hero": 10, "text": "Time to test the waters.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/9/90/Vo_morphling_mrph_spawn_08.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Morphling.json"}, {"hero": 10, "text": "Time for a good soaking.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/6/68/Vo_morphling_mrph_respawn_04.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Morphling.json"}, {"hero": 11, "text": "Не поминай мое имя всуе.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/a/ae/Nev_arc_spawn_07_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Shadow%20Fiend.json"}, {"hero": 11, "text": "Правду говорят у меня душа поэта вспомнить бы где она.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/b/b4/Nev_arc_rare_02_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Shadow%20Fiend.json"}, {"hero": 12, "text": "А ведь нас ещё больше.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/e/e9/Plance_respawn_05_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Phantom%20Lancer.json"}, {"hero": 12, "text": "Один за всех и все за одного.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/6/65/Plance_spawn_05_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Phantom%20Lancer.json"}, {"hero": 13, "text": "Fresh from death s chrysalis.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/0/0c/Vo_puck_puck_respawn_01.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Puck.json"}, {"hero": 13, "text": "I return to the active world.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/1/16/Vo_puck_puck_respawn_07.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Puck.json"}, {"hero": 14, "text": "Я не уходил просто ножи точил.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/3/3d/Pud_respawn_08_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Pudge.json"}, {"hero": 14, "text": "Так много мяса так мало времени.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/2/29/Pud_spawn_09_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Pudge.json"}, {"hero": 15, "text": "Загробный мир готов к новым поселенцам.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/7/7d/Raz_battlebegins_01_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Razor.json"}, {"hero": 15, "text": "Я заставлю врагов страдать за такое унижение.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/4/49/Raz_respawn_10_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Razor.json"}, {"hero": 16, "text": "Я боюсь лишь зелёных садов.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/f/f0/Skg_rare_05_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Sand%20King.json"}, {"hero": 16, "text": "Я каждого научу бояться песка.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/9/9d/Skg_rare_02_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Sand%20King.json"}, {"hero": 17, "text": "Я всё равно хотел отдохнуть.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/c/cc/Ss_respawn_06_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Storm%20Spirit.json"}, {"hero": 17, "text": "Тише всего бывает перед бурей.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/c/cb/Ss_respawn_07_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Storm%20Spirit.json"}, {"hero": 18, "text": "Это была всего лишь царапина.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/f/f4/Sven_respawn_12_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Sven.json"}, {"hero": 18, "text": "Мятежный рыцарь к вашим услугам.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/a/a0/Sven_spawn_02_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Sven.json"}, {"hero": 20, "text": "I will not fall again.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/b/b2/Vo_vengefulspirit_vng_respawn_04.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Vengeful%20Spirit.json"}, {"hero": 20, "text": "I fly on the winds of war.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/4/42/Vo_vengefulspirit_vng_battlebegins_01.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Vengeful%20Spirit.json"}, {"hero": 21, "text": "Ничего себе а это откуда.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/a/a2/Wind_drop_rare_01_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Windranger.json"}, {"hero": 21, "text": "Ура будет в кого пострелять.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/1/18/Wind_battlebegins_01_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Windranger.json"}, {"hero": 22, "text": "Надеюсь это не войдет в привычку.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/8/8e/Zuus_arc_respawn_02_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Zeus.json"}, {"hero": 22, "text": "Наступила новая эпоха я вернулся.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/5/55/Zuus_arc_respawn_04_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Zeus.json"}, {"hero": 23, "text": "В одно море дважды не войдёшь.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/1/1e/Kunk_respawn_07_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Kunkka.json"}, {"hero": 23, "text": "В пору бывалому морскому волку.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/e/eb/Kunk_spawn_10_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Kunkka.json"}, {"hero": 25, "text": "Меня так просто не затушить.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/7/78/Lina_respawn_02_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Lina.json"}, {"hero": 25, "text": "Мне кажется или тут стало жарко.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/9/98/Lina_respawn_05_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Lina.json"}, {"hero": 26, "text": "Hell hath no fury like me.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/a/af/Vo_lion_lion_spawn_05.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Lion.json"}, {"hero": 26, "text": "You summon the demon witch.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/c/cd/Vo_lion_lion_spawn_04.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Lion.json"}, {"hero": 27, "text": "Мой дух вернулся в тело.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/6/6f/Shad_respawn_05_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Shadow%20Shaman.json"}, {"hero": 27, "text": "Духи вернули меня к жизни.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/7/7a/Shad_respawn_02_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Shadow%20Shaman.json"}, {"hero": 28, "text": "Меня выманили в мир живых.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/2/20/Slar_respawn_06_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Slardar.json"}, {"hero": 28, "text": "Я сторожу покой на дне морском.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/6/68/Slar_rare_01_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Slardar.json"}, {"hero": 29, "text": "Оседлаем волну и накроем ею врагов.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/8/84/Tide_battlebegins_01_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Tidehunter.json"}, {"hero": 29, "text": "Обратим этот прилив себе на пользу.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/a/a0/Tide_battlebegins_02_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Tidehunter.json"}, {"hero": 30, "text": "Я всё ещё чувствую могильный холод.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/6/6d/Wdoc_respawn_11_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Witch%20Doctor.json"}, {"hero": 30, "text": "Терпенье и труд все кости перетрут.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/1/1a/Wdoc_rare_01_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Witch%20Doctor.json"}, {"hero": 31, "text": "Я скорее жив чем мёртв.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/7/7b/Lich_respawn_07_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Lich.json"}, {"hero": 31, "text": "Подобно зиме я всегда возвращаюсь.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/8/86/Lich_respawn_02_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Lich.json"}, {"hero": 32, "text": "Я был не мёртв просто невидим.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/6/66/Riki_respawn_08_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Riki.json"}, {"hero": 32, "text": "Убийство это мой труд мой хлеб.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/2/25/Riki_spawn_07_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Riki.json"}, {"hero": 33, "text": "My form collapses into being.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/5/5c/Vo_enigma_enig_spawn_04.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Enigma.json"}, {"hero": 33, "text": "I take form consumer of worlds.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/d/de/Vo_enigma_enig_spawn_06.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Enigma.json"}, {"hero": 34, "text": "Ready willing and fully enabled.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/b/b7/Vo_tinker_tink_spawn_03.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Tinker.json"}, {"hero": 34, "text": "Someone has hidden my glasses again.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/3/3c/Vo_tinker_tink_rare_03.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Tinker.json"}, {"hero": 35, "text": "Ещё на выстрел ближе к победе.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/6/62/Snip_respawn_03_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Sniper.json"}, {"hero": 35, "text": "Прицел курок врага валим с ног.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/1/1e/Snip_spawn_05_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Sniper.json"}, {"hero": 36, "text": "Меня так просто не сдержать.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/8/82/Necr_respawn_07_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Necrophos.json"}, {"hero": 36, "text": "Убивать или лечить всё едино.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/3/37/Necr_respawn_14_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Necrophos.json"}, {"hero": 37, "text": "I step from the shadows.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/2/2b/Vo_warlock_warl_respawn_03.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Warlock.json"}, {"hero": 37, "text": "A new fire from the embers.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/2/26/Vo_warlock_warl_respawn_06.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Warlock.json"}, {"hero": 38, "text": "Unleash the beasts of war.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/8/85/Vo_beastmaster_beas_spawn_05.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Beastmaster.json"}, {"hero": 38, "text": "Back on the endangered list.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/f/f8/Vo_beastmaster_beas_respawn_06.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Beastmaster.json"}, {"hero": 39, "text": "Будет боль и будут крики.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/b/bc/Pain_spawn_02_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Queen%20of%20Pain.json"}, {"hero": 39, "text": "Королева мертва да здравствует королева.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/1/1b/Pain_respawn_06_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Queen%20of%20Pain.json"}, {"hero": 40, "text": "Back from death s door.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/6/6d/Vo_venomancer_venm_respawn_01.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Venomancer.json"}, {"hero": 40, "text": "I ll make up for lost time.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/1/1a/Vo_venomancer_venm_respawn_07.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Venomancer.json"}, {"hero": 41, "text": "Time tells the mace fells.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/7/76/Vo_faceless_void_face_respawn_02.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Faceless%20Void.json"}, {"hero": 41, "text": "Like the sun i rise again.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/2/2c/Vo_faceless_void_face_respawn_01.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Faceless%20Void.json"}, {"hero": 42, "text": "Плоть и кости лишь мешают.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/c/c0/Wraith_respawn_01_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Wraith%20King.json"}, {"hero": 42, "text": "Меня не так просто одолеть.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/4/45/Wraith_respawn_08_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Wraith%20King.json"}, {"hero": 44, "text": "Полагаю меня рады видеть вновь.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/f/fb/Phass_arc_respawn_03_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Phantom%20Assassin.json"}, {"hero": 44, "text": "Позволь я отодвину завесу тайны.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/5/58/Phass_arc_respawn_05_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Phantom%20Assassin.json"}, {"hero": 45, "text": "Who dare cross my path.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/8/8a/Vo_pugna_pugna_spawn_03.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Pugna.json"}, {"hero": 45, "text": "I ll take all you have and more.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/0/0a/Vo_pugna_pugna_spawn_02.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Pugna.json"}, {"hero": 46, "text": "На этот раз я буду осторожнее.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/3/38/Temp_respawn_04_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Templar%20Assassin.json"}, {"hero": 46, "text": "Клянусь честью такое не повторится.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/5/57/Temp_respawn_06_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Templar%20Assassin.json"}, {"hero": 47, "text": "Feathers are for the weak.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/e/e8/Vo_viper_vipe_rare_02.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Viper.json"}, {"hero": 47, "text": "Enough waiting in the wings.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/c/c9/Vo_viper_vipe_respawn_04.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Viper.json"}, {"hero": 48, "text": "О они проклянут этот день.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/7/7e/Luna_respawn_06_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Luna.json"}, {"hero": 48, "text": "Лес в беде мой долг защитить его.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/d/d7/Luna_respawn_05_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Luna.json"}, {"hero": 49, "text": "The dragon comes for war.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/2/22/Vo_dragon_knight_dragon_spawn_02.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Dragon%20Knight.json"}, {"hero": 49, "text": "The shield of scale protects me.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/7/70/Vo_dragon_knight_dragon_respawn_03.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Dragon%20Knight.json"}, {"hero": 50, "text": "Я был там где тень это свет.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/1/17/Dazz_respawn_03_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Dazzle.json"}, {"hero": 50, "text": "Это вам не обычное посвящение.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/8/8c/Dazz_respawn_01_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Dazzle.json"}, {"hero": 51, "text": "Моя работа еще не закончена.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/4/4b/Ratt_respawn_08_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Clockwerk.json"}, {"hero": 51, "text": "Кручу верчу — собраться хочу.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/d/dd/Ratt_respawn_06_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Clockwerk.json"}, {"hero": 52, "text": "I come to tip the balance.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/5/50/Vo_leshrac_lesh_battlebegins_01.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Leshrac.json"}, {"hero": 52, "text": "I shall restore the imbalance.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/d/d7/Vo_leshrac_lesh_respawn_09.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Leshrac.json"}, {"hero": 53, "text": "I speak for the trees.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/0/09/Vo_furion_furi_spawn_01.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Nature%27s%20Prophet.json"}, {"hero": 53, "text": "I guard the wooded ways.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/6/64/Vo_furion_furi_spawn_03.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Nature%27s%20Prophet.json"}, {"hero": 54, "text": "And who is the master now.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/6/6d/Vo_life_stealer_lifest_respawn_13.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Lifestealer.json"}, {"hero": 54, "text": "Even death couldn t hold me.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/a/a4/Vo_life_stealer_lifest_respawn_08.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Lifestealer.json"}, {"hero": 55, "text": "No i will not calm my beard.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/c/cd/Vo_dark_seer_dkseer_rare_04.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Dark%20Seer.json"}, {"hero": 55, "text": "From darkness i surge to life.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/2/20/Vo_dark_seer_dkseer_respawn_04.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Dark%20Seer.json"}, {"hero": 56, "text": "Плоти нет и смерти нет.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/a/ab/Clinkz_respawn_01_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Clinkz.json"}, {"hero": 56, "text": "Мои стрелы разят без промаху.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/a/a5/Clinkz_spawn_04_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Clinkz.json"}, {"hero": 57, "text": "Моё время ещё не пришло.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/d/da/Omni_respawn_04_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Omniknight.json"}, {"hero": 57, "text": "Мой молот готов служить всезнающему.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/d/d4/Omni_spawn_04_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Omniknight.json"}, {"hero": 58, "text": "Light of foot light of heart.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/6/6e/Vo_enchantress_ench_spawn_02.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Enchantress.json"}, {"hero": 58, "text": "I ll not be tamed that easily.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/3/31/Vo_enchantress_ench_respawn_09.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Enchantress.json"}, {"hero": 59, "text": "Моя жизнь в надежных руках.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/5/5f/Husk_spawn_04_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Huskar.json"}, {"hero": 59, "text": "Неужели я всё еще недостоин.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/a/a7/Husk_respawn_06_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Huskar.json"}, {"hero": 60, "text": "The day needs the night.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/1/10/Vo_night_stalker_nstalk_respawn_02.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Night%20Stalker.json"}, {"hero": 60, "text": "Night waits in the wings.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/1/17/Vo_night_stalker_nstalk_respawn_09.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Night%20Stalker.json"}, {"hero": 61, "text": "Паучата так и рвутся наружу.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/a/a2/Brooo_spawn_02_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Broodmother.json"}, {"hero": 61, "text": "Жизней у меня больше чем лап.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/7/74/Brooo_respawn_01_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Broodmother.json"}, {"hero": 62, "text": "Любую дичь за ваши деньги.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/c/c3/Bount_battlebegins_01_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Bounty%20Hunter.json"}, {"hero": 62, "text": "Тут уже не в деньгах дело.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/8/85/Bount_respawn_11_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Bounty%20Hunter.json"}, {"hero": 63, "text": "I spring from the loom.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/2/2a/Vo_weaver_weav_respawn_11.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Weaver.json"}, {"hero": 63, "text": "More fates for me to weave.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/c/c4/Vo_weaver_weav_respawn_04.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Weaver.json"}, {"hero": 64, "text": "We rise from the ashes.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/6/61/Vo_jakiro_jak_respawn_05.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Jakiro.json"}, {"hero": 64, "text": "Two sides of the same coin.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/4/4c/Vo_jakiro_jak_spawn_05.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Jakiro.json"}, {"hero": 65, "text": "Эй кто спёр мои штаны.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/b/b9/Bat_respawn_06_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Batrider.json"}, {"hero": 65, "text": "Так где там мой головняк.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/4/4b/Bat_respawn_05_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Batrider.json"}, {"hero": 66, "text": "For obelis the one god.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/3/39/Vo_chen_chen_spawn_03.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Chen.json"}, {"hero": 66, "text": "Heme obelis calls me to service.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/b/b0/Vo_chen_chen_respawn_08.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Chen.json"}, {"hero": 67, "text": "From another dimension a world beyond.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/5/5a/Vo_spectre_spec_spawn_02.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Spectre.json"}, {"hero": 67, "text": "What strange properties this world has.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/7/76/Vo_spectre_spec_respawn_04.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Spectre.json"}, {"hero": 68, "text": "A new ice age dawns.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/6/6e/Vo_ancient_apparition_appa_respawn_09.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Ancient%20Apparition.json"}, {"hero": 68, "text": "The age of ice begins.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/a/ac/Vo_ancient_apparition_appa_spawn_02.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Ancient%20Apparition.json"}, {"hero": 69, "text": "Я открою вам врата ада.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/d/dc/Doom_respawn_09_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Doom.json"}, {"hero": 69, "text": "Падший вновь ступает по земле.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/8/89/Doom_spawn_04_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Doom.json"}, {"hero": 70, "text": "Я встаю на защиту своего племени.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/6/63/Ursa_spawn_02_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Ursa.json"}, {"hero": 70, "text": "Я слышал как духи взывали ко мне.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/e/e1/Ursa_respawn_05_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Ursa.json"}, {"hero": 71, "text": "Моё тело вновь обретает форму.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/3/37/Spir_respawn_08_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Spirit%20Breaker.json"}, {"hero": 71, "text": "Кстати кто в этом мире главный.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/6/6a/Spir_rare_04_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Spirit%20Breaker.json"}, {"hero": 72, "text": "Староват я уже для всей этой фигни.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/3/3d/Gyro_respawn_12_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Gyrocopter.json"}, {"hero": 72, "text": "Если в аварии выживаешь она не считается.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/7/7d/Gyro_respawn_04_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Gyrocopter.json"}, {"hero": 73, "text": "Я вот что скажу ты хорош.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/4/42/Alch_rare_02_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Alchemist.json"}, {"hero": 73, "text": "Надо бы улучшить эту формулу.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/c/c6/Alch_respawn_03_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Alchemist.json"}, {"hero": 74, "text": "Без меня вселенная уже не та.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/3/36/Invo_respawn_05_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Invoker.json"}, {"hero": 74, "text": "Линия без начала линия без конца.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/1/1d/Invo_respawn_08_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Invoker.json"}, {"hero": 75, "text": "Я несу вам дар тишины.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/5/5a/Silen_spawn_03_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Silencer.json"}, {"hero": 75, "text": "Я вернулся из мира великой тишины.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/4/40/Silen_respawn_01_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Silencer.json"}, {"hero": 76, "text": "Мои крылья вновь полны жизни.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/5/52/Odest_respawn_02_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Outworld%20Devourer.json"}, {"hero": 76, "text": "Я ненадолго ушёл во внешнюю тьму.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/d/dc/Odest_respawn_01_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Outworld%20Devourer.json"}, {"hero": 77, "text": "The trails will run red.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/b/bf/Vo_lycan_lycan_battlebegins_02.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Lycan.json"}, {"hero": 77, "text": "The wolf comes round again.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/f/fb/Vo_lycan_lycan_respawn_05.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Lycan.json"}, {"hero": 78, "text": "What kind of pub is this.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/e/e1/Vo_brewmaster_brew_spawn_05.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Brewmaster.json"}, {"hero": 78, "text": "Yoy and oyo return me to life.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/1/15/Vo_brewmaster_brew_respawn_08.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Brewmaster.json"}, {"hero": 79, "text": "Take care what you summon.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/5/5a/Vo_shadow_demon_shadow_demon_respawn_03.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Shadow%20Demon.json"}, {"hero": 79, "text": "Let me pull myself together.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/a/ad/Vo_shadow_demon_shadow_demon_respawn_02.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Shadow%20Demon.json"}, {"hero": 80, "text": "I take root once more.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/3/3c/Vo_lone_druid_lone_druid_bearform_respawn_02.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Lone%20Druid.json"}, {"hero": 80, "text": "The seed shall be sown.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/5/57/Vo_lone_druid_lone_druid_bearform_spawn_04.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Lone%20Druid.json"}, {"hero": 81, "text": "The dark horseman rides anew.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/9/92/Vo_chaos_knight_chaknight_respawn_04.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Chaos%20Knight.json"}, {"hero": 81, "text": "I am born anew to this plane.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/5/57/Vo_chaos_knight_chaknight_respawn_09.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Chaos%20Knight.json"}, {"hero": 82, "text": "Будем рыть рыть рыть рыть.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/c/c1/Meepo_spawn_03_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Meepo.json"}, {"hero": 82, "text": "Могила не волк в лес не убежит.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/3/3b/Meepo_respawn_03_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Meepo.json"}, {"hero": 83, "text": "I rather enjoyed that break.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/4/4e/Vo_treant_treant_respawn_11.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Treant%20Protector.json"}, {"hero": 83, "text": "The seasons wheel past in a blur.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/0/08/Vo_treant_treant_spawn_05.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Treant%20Protector.json"}, {"hero": 84, "text": "После вас нет я первый.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/f/fa/Ogmag_spawn_06_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Ogre%20Magi.json"}, {"hero": 84, "text": "Что ещё рано я то думал уже пора.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/e/eb/Ogmag_battlebegins_01_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Ogre%20Magi.json"}, {"hero": 85, "text": "I bring the song of death.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/d/d5/Vo_undying_undying_big_spawn_04.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Undying.json"}, {"hero": 85, "text": "No hells no heavens only this.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/8/86/Vo_undying_undying_big_respawn_05.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Undying.json"}, {"hero": 86, "text": "Это поле боя полно чудес.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/2/24/Rubick_respawn_06_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Rubick.json"}, {"hero": 86, "text": "Какие чудеса узрею я сегодня.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/1/12/Rubick_spawn_03_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Rubick.json"}, {"hero": 87, "text": "Моя месть войдёт в легенды.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/2/26/Dis_respawn_07_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Disruptor.json"}, {"hero": 87, "text": "Кто разогнал надо мною тучи.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/1/17/Dis_respawn_12_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Disruptor.json"}, {"hero": 88, "text": "У никс всегда есть убийцы.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/3/3d/Nyx_respawn_12_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Nyx%20Assassin.json"}, {"hero": 88, "text": "Мой разум снова населяет плоть.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/6/61/Nyx_respawn_07_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Nyx%20Assassin.json"}, {"hero": 89, "text": "I rise against the tide.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/f/f1/Vo_naga_siren_naga_respawn_03.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Naga%20Siren.json"}, {"hero": 89, "text": "The song of war commences.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/6/6c/Vo_naga_siren_naga_spawn_06.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Naga%20Siren.json"}, {"hero": 90, "text": "Свет привёл меня на этот путь.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/2/20/Keep_spawn_04_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Keeper%20of%20the%20Light.json"}, {"hero": 90, "text": "Эзалор по моему так меня зовут.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/3/38/Keep_respawn_12_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Keeper%20of%20the%20Light.json"}, {"hero": 92, "text": "Once more from my perch.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/5/56/Vo_visage_visa_respawn_10.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Visage.json"}, {"hero": 92, "text": "I have only been delayed.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/4/42/Vo_visage_visa_respawn_03.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Visage.json"}, {"hero": 93, "text": "Такой густой воздух нечем дышать.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/0/0f/Slark_respawn_03_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Slark.json"}, {"hero": 93, "text": "Не будешь мешать останешься цел наверное.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/b/bc/Slark_battlebegins_01_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Slark.json"}, {"hero": 94, "text": "I will not fail again.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/c/c0/Vo_medusa_medus_respawn_05.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Medusa.json"}, {"hero": 94, "text": "The only real beauty is power.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/9/9c/Vo_medusa_medus_rare_07.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Medusa.json"}, {"hero": 95, "text": "All hail the lord of trolls.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/a/a3/Vo_troll_warlord_troll_spawn_03.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Troll%20Warlord.json"}, {"hero": 95, "text": "My hate shall burn you down.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/c/c0/Vo_troll_warlord_troll_spawn_06.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Troll%20Warlord.json"}, {"hero": 96, "text": "Моё дело ещё не закончено.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/1/1a/Cent_respawn_06_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Centaur%20Warrunner.json"}, {"hero": 96, "text": "Вновь выхожу на поле битвы.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/e/ed/Cent_respawn_05_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Centaur%20Warrunner.json"}, {"hero": 97, "text": "Let them try and stop me.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/2/23/Vo_magnataur_magn_spawn_02.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Magnus.json"}, {"hero": 97, "text": "Keep your eye on my horn.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/9/95/Vo_magnataur_magn_spawn_05.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Magnus.json"}, {"hero": 98, "text": "Trees why did it have to be trees.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/c/c0/Vo_shredder_timb_respawn_02.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Timbersaw.json"}, {"hero": 98, "text": "This this is what i have always wanted always.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/3/31/Vo_shredder_timb_drop_rare_01.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Timbersaw.json"}, {"hero": 99, "text": "Что это я снова здесь.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/c/c0/Bristle_respawn_07_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Bristleback.json"}, {"hero": 99, "text": "Как же вы тут без меня.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/2/2e/Bristle_respawn_03_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Bristleback.json"}, {"hero": 100, "text": "Отлично я вернулся ещё повоюем.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/8/82/Tusk_respawn_07_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Tusk.json"}, {"hero": 100, "text": "Да меня хватит ещё на пару ударов.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/3/36/Tusk_respawn_02_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Tusk.json"}, {"hero": 101, "text": "Жуткое гнездо ждёт её с нетерпением.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/e/e2/Drag_respawn_07_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Skywrath%20Mage.json"}, {"hero": 101, "text": "Месть она важнее меня важнее всего вокруг.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/a/a4/Drag_respawn_08_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Skywrath%20Mage.json"}, {"hero": 102, "text": "Со мною вся династия аверно.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/b/bd/Abad_spawn_05_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Abaddon.json"}, {"hero": 102, "text": "Это место будто проблеск в тумане.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/1/1f/Abad_spawn_03_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Abaddon.json"}, {"hero": 103, "text": "From perfect unity i come.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/0/08/Vo_elder_titan_elder_spawn_07.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Elder%20Titan.json"}, {"hero": 103, "text": "The five founders united again.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/f/f8/Vo_elder_titan_elder_spawn_08.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Elder%20Titan.json"}, {"hero": 104, "text": "Отступление хах а что это.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/b/bd/Legcom_dem_respawn_12_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Legion%20Commander.json"}, {"hero": 104, "text": "Меня так просто не сломить.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/5/50/Legcom_dem_respawn_11_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Legion%20Commander.json"}, {"hero": 105, "text": "Oh my ears are still ringing huh.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/b/ba/Vo_techies_tech_respawn_ssa_02.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Techies.json"}, {"hero": 105, "text": "Are we alive or dead let s find out.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/6/69/Vo_techies_tech_respawn_11.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Techies.json"}, {"hero": 106, "text": "Увёл прямо из под носа.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/a/ab/Embr_deny_04_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Ember%20Spirit.json"}, {"hero": 106, "text": "Сейчас кому то будет жарко.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/2/2b/Embr_attack_02_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Ember%20Spirit.json"}, {"hero": 107, "text": "Земной шар питает мой дух.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/7/76/Earthspi_spawn_03_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Earth%20Spirit.json"}, {"hero": 107, "text": "Мой дух вернулся в земной мир.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/6/6e/Earthspi_respawn_11_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Earth%20Spirit.json"}, {"hero": 108, "text": "Кто посмел воззвать ко мне.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/5/57/Abys_spawn_06_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Underlord.json"}, {"hero": 108, "text": "Я знаю где развешу их черепа.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/6/60/Abys_rare_04_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Underlord.json"}, {"hero": 109, "text": "I appear unto the world.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/2/2c/Vo_terrorblade_terr_shards_spawn_02.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Terrorblade.json"}, {"hero": 109, "text": "My journey is far from over.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/0/04/Vo_terrorblade_terr_shards_respawn_10.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Terrorblade.json"}, {"hero": 111, "text": "Again again and once again.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/d/d9/Vo_oracle_orac_respawn_01.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Oracle.json"}, {"hero": 111, "text": "Is it really that time again.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/6/61/Vo_oracle_orac_respawn_10.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Oracle.json"}, {"hero": 112, "text": "Кто спал на моих сокровищах.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/e/e2/Winwyv_respawn_11_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Winter%20Wyvern.json"}, {"hero": 112, "text": "Да падут враги под моей тенью.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/1/11/Winwyv_battlebegins_01_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Winter%20Wyvern.json"}, {"hero": 113, "text": "Самость на время примкнёт к свету.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/d/da/Arcwar_spawn_06_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Arc%20Warden.json"}, {"hero": 113, "text": "Самость на время примкнёт ко тьме.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/a/a5/Arcwar_spawn_08_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Arc%20Warden.json"}, {"hero": 114, "text": "Знаю я все эти легенды.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/6/6f/Monkey_crown_spawn_21_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Monkey%20King.json"}, {"hero": 114, "text": "Как долго я ждал испытания.", "lang": "ru", "audio": "https://static.wikia.nocookie.net/dota2_ru_gamepedia/images/9/97/Monkey_crown_spawn_06_ru.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/ru_replics/Monkey%20King.json"}, {"hero": 119, "text": "No rest for the wicked.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/3/3c/Vo_dark_willow_sylph_respawn_09.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Dark%20Willow.json"}, {"hero": 119, "text": "Time to take what i want.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/6/64/Vo_dark_willow_sylph_spawn_09.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Dark%20Willow.json"}, {"hero": 120, "text": "Best two out of three.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/7/71/Vo_pangolin_pangolin_respawn_10.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Pangolier.json"}, {"hero": 120, "text": "Let s keep this between us.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/d/dd/Vo_pangolin_pangolin_respawn_05.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Pangolier.json"}, {"hero": 121, "text": "I will not falter again.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/8/87/Vo_grimstroke_grimstroke_respawn_10.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Grimstroke.json"}, {"hero": 121, "text": "Time for the master stroke.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/b/bc/Vo_grimstroke_grimstroke_spawn_03_02.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Grimstroke.json"}, {"hero": 126, "text": "I return from the temple.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/2/2f/Vo_void_spirit_voidspir_respawn_06.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Void%20Spirit.json"}, {"hero": 126, "text": "I stay true to the course.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/9/95/Vo_void_spirit_voidspir_respawn_09.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Void%20Spirit.json"}, {"hero": 128, "text": "Time to point and click.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/4/40/Vo_snapfire_snapfire_spawn_21.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Snapfire.json"}, {"hero": 128, "text": "I just make it look easy.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/4/48/Vo_snapfire_snapfire_spawn_13.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Snapfire.json"}, {"hero": 129, "text": "A god by any other name.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/2/22/Vo_mars_mars_spawn_05_03.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Mars.json"}, {"hero": 129, "text": "Ahh it s not like today.", "lang": "en", "audio": "https://static.wikia.nocookie.net/dota2_gamepedia/images/5/5a/Vo_mars_mars_rare_07.mp3", "source": "https://github.com/dota2tools/dtrspnsy/blob/master/dtrspnsy/en_replics/Mars.json"}];
